+    private static JsonNode unwrapReplayResponseNode(JsonNode node) throws Exception {
+        if (node == null) {
+            throw new Exception("empty replay response");
+        }
+        if (node.isTextual()) {
+            return OBJECT_MAPPER.readTree(node.asText());
+        }
+        return node;
