+                Updates.setOnInsert("userId", userId),
+                Updates.set("screenshotsBase64", screenshotsBase64),
+                Updates.set("updatedAt", Context.now())
+        );
+        RecordedLoginScreenshotDao.instance.updateOne(filter, update);
+    }
